#include <string>
#include <algorithm>

class Solution {
public:
    long long sumSortableIntegers(int low, int high) {
        long long total = 0;
        for (int x = low; x <= high; ++x) {
            std::string s = std::to_string(x);
            if (std::is_sorted(s.begin(), s.end())) total += x;
        }
        return total;
    }
};

class Solution {
    public long sumSortableIntegers(int low, int high) {
        long total = 0;
        for (int x = low; x <= high; x++) {
            String s = String.valueOf(x);
            boolean sorted = true;
            for (int i = 1; i < s.length(); i++) {
                if (s.charAt(i) < s.charAt(i - 1)) {
                    sorted = false;
                    break;
                }
            }
            if (sorted) total += x;
        }
        return total;
    }
}

function sumSortableIntegers(low, high) {
